import {getLanguage} from './i18n.js';
import {ac,aerBrand,aerScene} from './aer-art.js';
import {aerLinks,aerAsset} from './aer-content.js';

export const aerPost={
  id:'aer',theme:'aer',number:'15',date:'2026-10-02',version:'1.0.0',cover:aerAsset+'home.webp',image:aerAsset+'results.webp',link:aerLinks.site,
  zh:{
    category:'出发手记 / AER 1.0',title:'为下一程，留一片透明的天空。',
    summary:'冰蓝的天光、近乎无色的玻璃，还有慢慢转动的航司尾翼。AER 是一次把旅行的向往，做成可以搜索、比较和留下偏好的空间的尝试。',
    lead:'我一直喜欢远方。但在真正出发以前，旅程往往先发生在屏幕上：一个城市、一条弧线、一个觉得还不错的起飞时间。做 AER 时，我想把这个还没起飞的时刻，留得轻盈一点。',
    quote:'玻璃没有自己的天空。\n它把世界的颜色，借来一会儿。',
    sections:[
      {title:'想去的地方，先在屏幕里相遇',paragraphs:['在迪拜生活，很容易对“下一程”保持想象。地图上的城市看起来很近，真正选择一趟航班时，时间、转机、预算和熟悉的航司又会慢慢浮现。我想把这些选择放进同一张可以平静观看的画面里。','于是有了 AER。搜索从出发地与目的地开始，接着是日期、旅客和舱位；结果可以筛选、排序，也可以把几段行程放在一起比较。不是每个人都想要同一趟航班，所以界面里也应该有属于个人的节奏。']},
      {title:'让玻璃，真的允许世界穿过',paragraphs:['我喜欢的透明玻璃，不是给一块白色卡片加上模糊。AER 的玻璃几乎没有自己的颜色：弧面边缘留下一条细白的亮线，背面有很浅的阴影，光经过时，会轻轻折向另一边。冰蓝、淡紫和一点暖白来自玻璃背后的天空。','尾翼保留原来的涂装，材质只负责让它获得一点厚度和反射。展柜里的光学环、悬浮底座与掠过表面的亮光，继续了这个想法：让玻璃被看见，也让透过玻璃的东西被看见。运动常驻，但不急着争夺文字的注意力。']},
      {title:'比一条路线，多一点自己的节奏',paragraphs:['AER 里还有一张旅人签名。熟悉哪些航司，喜欢何时出发，是否愿意转机，怎样在时间和票价之间取舍，这些小偏好会被整理成一片星图。保存的选择和正负反馈，也会改变后面的推荐倾向。','推荐使用可以解释的权重，而不是给人看一个神秘的分数。行程为什么更符合偏好，应该能读懂。账户、历史与选择记录由访问者的身份分开保存；一段旅程的推荐，也可以在下一次选择后慢慢变得更像自己。']},
      {title:'一枚尾翼，也需要一份准确的身份',paragraphs:['做这类页面，很容易因为某张飞机图漂亮，就把它放到所有行程旁边。我不想这样。航司、准确机型与注册号是不同层次的信息：A350-900 与 A350-1000、787-9 与 787-10，应该分别找到对应的插画。','AER 的机队参考还能从注册号看见已收录的型号与来源。有些记录是历史快照，有些涂装资料只覆盖特定机身；不知道的部分就留白。展柜里的阿联酋航空 A380 插画也保留作者和许可，漂亮与准确可以同时存在。']},
      {title:'先把选择留下，远方还可以继续长大',paragraphs:['现在的 AER 1.0 是需要授权访问的私人作品。航班时刻和票价用于演示，选中行程会保存一条意向记录，不会创建预订、付款或机票。真实供应商报价的适配接口已经写进工程，但没有拿未验证的连接来当成实时能力。','我先把这间玻璃里的候机室留在自己的作品集里。以后它可以继续生长；今天最想记住的，是一个关于远方的想法，终于有了可以看见、可以点击、可以走进去的形状。保持热忱，保持热爱。下一程，慢慢来。']}
    ],afterword:'2026.10.02 / 写在迪拜。为每一次还没发生的出发。',cta:'打开 AER 私人站点'
  },
  en:{
    category:'DEPARTURE NOTES / AER 1.0',title:'A clearer sky for the next journey.',
    summary:'Ice-blue daylight, nearly colourless glass and airline tails slowly turning in space. AER turns the thought of travel into a place to explore, compare and keep a personal rhythm.',
    lead:'I have always been drawn to places further away. Before a departure becomes real, it often begins on a screen: a city, an arc across a map, a departure time that feels right. AER gives that moment before take-off a little more room to breathe.',
    quote:'Glass has no sky of its own.\nIt borrows the world’s colours for a moment.',
    sections:[
      {title:'Let the next place meet you on screen',paragraphs:['Living in Dubai leaves plenty of room to imagine the next journey. Cities seem close on a map; choosing a flight brings time, connections, budget and familiar airlines into view. I wanted those choices to share one calm space.','AER begins with origin and destination, then dates, travellers and cabin. Results can be filtered, sorted and compared. Different people want different departures. A flight interface should have room for that personal rhythm.']},
      {title:'Glass that lets the world pass through',paragraphs:['The glass I wanted is more than a blurred white card. AER’s optical surfaces are almost colourless: a narrow white rim, a soft shadow behind the edge, and light that bends slightly as it passes. Ice blue, lilac and warm white belong to the sky behind the material.','Airline tails keep their original livery. Depth and reflection give the illustration a small volume. The exhibit’s optical ring, floating plinth and moving highlights carry that idea further: make the glass visible, while keeping what lies beyond it visible too. The motion stays present without rushing the reading.']},
      {title:'A route, with a little more of you',paragraphs:['AER also holds a traveller signature. Familiar airlines, preferred departure times, willingness to connect, and the balance between price and time become a constellation of preferences. Saved choices and positive or negative feedback change later recommendations.','The recommendations use explainable weights rather than an unexplained score on screen. A visitor should be able to understand why a journey fits. Profiles, history and choices are scoped to the authenticated visitor, so a signature can gradually develop with its owner.']},
      {title:'Even a tail needs the right identity',paragraphs:['A beautiful aircraft illustration should not be used indiscriminately. Operating airline, precise aircraft variant and registration are different layers of information. An A350-900 is not an A350-1000; a 787-9 is not a 787-10. Each should have the right reference.','The Fleet Atlas follows registrations to recorded models and sources. Some records are historical snapshots, and some special liveries belong to a single airframe. Missing information stays missing. The Emirates A380 illustration in this exhibit retains its author and licence: accuracy belongs alongside the art.']},
      {title:'Keep the choice. Leave the horizon open.',paragraphs:['AER 1.0 is currently a private project requiring authorised access. Flight schedules and fares are demonstrative. Selecting a journey saves a shortlist entry; it does not create a booking, payment or ticket. A supplier adapter exists in the code, but an unverified connection is not presented as a live capability.','For now, this glass departure lounge joins my own collection. It can keep growing. What I want to remember today is that a thought about a further horizon has become something visible, clickable and possible to walk into. Keep loving life. The next departure can take its time.']}
    ],afterword:'2 October 2026 / Written in Dubai, for departures still ahead.',cta:'Open the private AER site'
  }
};
const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function plate(index){
  if(index===0)return `<figure class="aer-screen-figure"><div class="aer-screen-rim"></div><img src="${aerAsset}home.webp" width="1425" height="1460" alt="${ac('AER 1.0 的透明玻璃主页，显示本地演示航班','AER 1.0 optical-glass homepage with local demonstration flights')}" loading="lazy"><figcaption>PLATE I / ${ac('真实软件界面，本地演示数据','ACTUAL APPLICATION / LOCAL DEMONSTRATION DATA')}</figcaption></figure>`;
  if(index===1)return `<div class="aer-reader-material">${aerScene({kind:'material'})}<span>${ac('持续转动的光学标本 / 展柜艺术','A LIVING OPTICAL SPECIMEN / EXHIBITION ART')}</span></div>`;
  if(index===2)return `<figure class="aer-screen-figure aer-screen-figure--results"><div class="aer-screen-rim"></div><img src="${aerAsset}results.webp" width="871" height="1800" alt="${ac('AER 演示行程的搜索与比较界面','AER search and comparison interface with demonstration journeys')}" loading="lazy"><figcaption>PLATE II / ${ac('真实软件界面；时刻与价格用于演示','ACTUAL APPLICATION / DEMONSTRATIVE SCHEDULES AND FARES')}</figcaption></figure>`;
  if(index===3)return `<figure class="aer-aircraft-figure"><span>EMIRATES / AIRBUS A380-800</span><img src="${aerAsset}emirates-a380.webp" width="1600" height="505" alt="${ac('阿联酋航空 A380-800 插画','Emirates A380-800 illustration')}" loading="lazy"><figcaption><a href="https://commons.wikimedia.org/wiki/File:A380-Emirates.png" target="_blank" rel="noopener noreferrer">Fred053</a> / <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a> · ${ac('原插画缩放为 WebP','Original illustration resized to WebP')}</figcaption></figure>`;
  return '';
}
export function renderAerReader(){
  const text=aerPost[getLanguage()];
  const displayTitle=ac('<span>为下一程，</span><span><span class="aer-title-prefix">留一片</span><span class="aer-title-sky">透明的天空。</span></span>',safe(text.title));
  return `<nav class="reader-topline" aria-label="${ac('文章导航','Article navigation')}"><a href="./posts.html">← ${ac('所有随笔','ALL POSTS')}</a><span>NOTE 015 / THE DEPARTURE COLLECTION</span></nav><article class="aer-reader" aria-labelledby="article-title"><header class="aer-reader-header"><div class="aer-editorial-meta"><span>${text.category}</span><time datetime="2026-10-02">2026.10.02</time></div><div class="aer-editorial-brand">${aerBrand}<span>aer</span><sup>®</sup></div><h1 id="article-title">${displayTitle}</h1><p class="aer-reader-deck">${text.summary}</p><div class="aer-reader-byline"><span>CHEFZC</span><i></i><span>${ac('写在热爱里','NOTES FROM MY WORLD')}</span><span>V 1.0</span></div></header><div class="aer-reader-overture">${aerScene({kind:'editorial'})}<span class="aer-editorial-whisper">A LITTLE CLOSER.<br>A LITTLE MORE YOU.</span><div class="aer-reader-overture-foot"><span>GLASS / REFRACTION / DEPARTURE</span><span>01 / AER</span></div></div><div class="aer-editorial-grid"><aside class="aer-editorial-aside"><span>ON THIS JOURNEY</span><ol>${text.sections.map((s,i)=>`<li><a href="#chapter-${i+1}"><b>0${i+1}</b>${safe(s.title)}</a></li>`).join('')}</ol><div class="aer-aside-ornament" aria-hidden="true"><i></i><span>25°15′ N</span><b>DXB</b></div></aside><div class="aer-editorial-body"><p class="aer-reader-lead">${text.lead}</p>${text.sections.map((s,i)=>`<section class="aer-editorial-chapter" id="chapter-${i+1}"><span class="aer-overline">0${i+1} / ${['THE NEXT HORIZON','THE OPTICAL MATERIAL','THE TRAVELLER SIGNATURE','THE RIGHT AIRCRAFT','A JOURNEY IN PROGRESS'][i]}</span><h2>${safe(s.title)}</h2>${s.paragraphs.map(p=>`<p>${safe(p)}</p>`).join('')}${i===0?`<blockquote>${safe(text.quote).replace('\n','<br>')}<span aria-hidden="true">↗</span></blockquote>`:''}${plate(i)}</section>`).join('')}<footer class="aer-reader-tail"><p>${text.afterword}</p><strong>ChefZC<span>_</span></strong><div class="aer-actions"><a href="${aerLinks.site}" target="_blank" rel="noopener noreferrer">${text.cta} ↗<small>${ac('需要授权访问','AUTHORISED ACCESS')}</small></a><a href="${aerLinks.gallery}">${ac('回到玻璃展柜','Back to the glass exhibit')} ↗</a></div></footer></div></div></article><section class="more-notes"><div class="posts-section-label"><span>${ac('继续探索','CONTINUE EXPLORING')}</span><a href="./posts.html">${ac('所有随笔','ALL POSTS')} ↗</a></div><div><a class="next-note next-note--aer" href="${aerLinks.gallery}"><span class="mono">THE DEPARTURE COLLECTION</span><h2>${ac('再看一会儿，光穿过玻璃。','Stay a moment. Let the light pass through.')}</h2><span>↗</span></a><a class="next-note" href="${aerLinks.now}"><span class="mono">2026.10.02 / NOW</span><h2>${ac('把这次出发，留在时间线上。','A place for this departure in the timeline.')}</h2><span>↗</span></a></div></section>`;
}
